-- Tanda 2 de sesiones de idiomas (V1.0.2): continuidad real tras la sesion 1 de cada idioma.
-- Idempotente: no se duplica si ya existe una sesion con ese lang+day.
insert into lessons (lang, day, title, body, quiz)
select * from (values
('en', 2, 'Inglés 2: tu rutina en presente', '<p>El presente simple para hablar de tu día a día. Tercera persona lleva -s, contigo va sin nada:</p><p class="mt"><b>I get up at eight.</b> (Me levanto a las ocho)<br><b>I go to class by train.</b> (Voy a clase en tren)<br><b>I study networking.</b> (Estudio redes)<br><b>I play video games at night.</b> (Juego a videojuegos por la noche)</p><p class="mt">Truco: escribe tu rutina real en 4 frases con este molde y léela en voz alta 3 veces. Que sea verdad, así se queda antes.</p>', '[{"q": "¿Cómo se dice ''Voy a clase en tren''?", "opts": ["I go to class by train", "I go class train", "I going to class by train"], "a": 0}, {"q": "Completa: ''She ___ up at seven.'' (ella se levanta)", "opts": ["get", "gets", "getting"], "a": 1}, {"q": "¿Qué significa ''I study networking''?", "opts": ["Estudio redes", "Trabajo en redes", "Estudié redes ayer"], "a": 0}]'::jsonb),
('en', 3, 'Inglés 3: preguntas sin miedo', '<p>Las 4 preguntas que más vas a usar, con su respuesta corta:</p><p class="mt"><b>What''s your name?</b> → I''m Samuel.<br><b>Where are you from?</b> → I''m from Madrid.<br><b>How old are you?</b> → I''m twenty.<br><b>Do you like music?</b> → Yes, I do. / No, I don''t.</p><p class="mt">Truco: con verbos normales la pregunta lleva <b>do/does</b> delante. Con el verbo <i>to be</i> no: se invierte (<i>Are you...?</i>, no <i>Do you are...?</i>).</p>', '[{"q": "¿Cuál es la pregunta correcta?", "opts": ["Where are you from?", "Where you are from?", "Where do you from?"], "a": 0}, {"q": "Responde a ''Do you like music?''", "opts": ["Yes, I do", "Yes, I like", "Yes, I am"], "a": 0}, {"q": "Completa: ''___ old are you?'' (¿Cuántos años tienes?)", "opts": ["How", "What", "Who"], "a": 0}]'::jsonb),
('en', 4, 'Inglés 4: en la cafetería', '<p>Pedir sin señalar con el dedo:</p><p class="mt"><b>Can I have a coffee, please?</b> (¿Me pones un café, por favor?)<br><b>Anything to eat?</b> → <b>Just the coffee, thanks.</b> (Solo el café, gracias)<br><b>How much is it?</b> (¿Cuánto es?)<br><b>Can I pay by card?</b> (¿Puedo pagar con tarjeta?)</p><p class="mt">Truco: <b>Can I have...?</b> te vale para todo: café, agua, la cuenta (<i>the bill</i>). Educado y fácil.</p>', '[{"q": "¿Cómo pides un café educadamente?", "opts": ["Can I have a coffee, please?", "Give me a coffee now", "I want coffee yes"], "a": 0}, {"q": "¿Qué significa ''How much is it''?", "opts": ["¿Cuánto es?", "¿Dónde está?", "¿Qué es esto?"], "a": 0}, {"q": "Completa: ''Can I pay ___ card?''", "opts": ["by", "with", "in"], "a": 0}]'::jsonb),
('en', 5, 'Inglés 5: qué te gusta (y qué no)', '<p>Para hablar de gustos, el verbo lleva <b>-ing</b> detrás de like/love/hate:</p><p class="mt"><b>I like watching anime.</b> (Me gusta ver anime)<br><b>I love playing video games.</b> (Me encanta jugar a videojuegos)<br><b>I don''t like getting up early.</b> (No me gusta levantarme temprano)<br><b>Do you like cooking?</b> → Yes, I do.</p><p class="mt">Truco: like + verbo-ing. Si dices <i>I like watch</i> suena raro; es <i>I like watching</i>.</p>', '[{"q": "¿Cómo se dice ''Me gusta ver anime''?", "opts": ["I like watching anime", "I like watch anime", "I liking watch anime"], "a": 0}, {"q": "¿Qué significa ''I don''t like getting up early''?", "opts": ["No me gusta levantarme temprano", "Me encanta madrugar", "No me levanto nunca"], "a": 0}, {"q": "Completa: ''I love ___ video games.''", "opts": ["playing", "play", "played"], "a": 0}]'::jsonb),
('en', 6, 'Inglés 6: la hora y los días', '<p>Preguntar y decir la hora sin líos:</p><p class="mt"><b>What time is it?</b> (¿Qué hora es?)<br><b>It''s half past eight.</b> (Son las ocho y media)<br><b>It''s quarter to five.</b> (Son las cinco menos cuarto)<br><b>Class starts at nine.</b> (La clase empieza a las nueve)</p><p class="mt">Días: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday. Van con <b>on</b>: <i>I have class on Monday</i>.</p><p class="mt">Truco: <i>half past</i> = y media; <i>quarter to</i> = menos cuarto. Con eso cubres casi todo.</p>', '[{"q": "¿Qué hora es si dicen ''It''s half past eight''?", "opts": ["Las ocho y media", "Las ocho menos cuarto", "Las nueve en punto"], "a": 0}, {"q": "Completa: ''I have class ___ Monday.''", "opts": ["on", "in", "at"], "a": 0}, {"q": "¿Cómo se pregunta la hora?", "opts": ["What time is it?", "What hour is it?", "How is the time?"], "a": 0}]'::jsonb),
('ja', 2, 'Hiragana 2: fila S', '<p class="jp">さ sa · し shi · す su · せ se · そ so</p><p class="mt">Trucos: さ parece una "sa" sin la barra de arriba. し es un anzuelo (shi tiene gancho). す es una espiral (su-enrollado). せ parece una "se" de espalda. そ es un lazo en zigzag (so... zzz).</p><p class="mt">Ojo: la fila S es la única que rompe el patrón: no es si, es <b>shi</b>.</p><p class="mt">Ya puedes leer: あさ (asa, mañana), すし (sushi), いす (isu, silla), そら (sora, cielo), かさ (kasa, paraguas).</p>', '[{"q": "¿Qué sonido es し?", "opts": ["shi", "si", "chi"], "a": 0}, {"q": "¿Qué sonido es す?", "opts": ["su", "sa", "so"], "a": 0}, {"q": "¿Qué significa そら (sora)?", "opts": ["cielo", "silla", "mañana"], "a": 0}]'::jsonb),
('ja', 3, 'Hiragana 3: filas T y N', '<p class="jp">た ta · ち chi · つ tsu · て te · と to<br>な na · に ni · ぬ nu · ね ne · の no</p><p class="mt">Trucos: た parece una "ta" con patas. ち es un niño saltando (chi). つ es una ola pequeña (tsu-nami). て es una mano (te significa mano). と es un dedo señalando (to). な tiene un nudo (na). に son dos palitos con uno pequeño (ni = dos). ね es un gato enroscado (ne-ko). の es una espiral suave.</p><p class="mt">Dos trampas más del patrón: no es ti, es <b>chi</b>; y no es tu, es <b>tsu</b>.</p><p class="mt">Ya puedes leer: ねこ (neko, gato), いぬ (inu, perro), つき (tsuki, luna), なつ (natsu, verano), て (te, mano).</p>', '[{"q": "¿Qué sonido es ち?", "opts": ["chi", "ti", "shi"], "a": 0}, {"q": "¿Qué sonido es つ?", "opts": ["tsu", "tu", "su"], "a": 0}, {"q": "¿Qué significa ねこ (neko)?", "opts": ["gato", "perro", "luna"], "a": 0}]'::jsonb),
('ja', 4, 'Hiragana 4: filas H y M', '<p class="jp">は ha · ひ hi · ふ fu · へ he · ほ ho<br>ま ma · み mi · む mu · め me · も mo</p><p class="mt">Trucos: は parece una persona con sombrero (ha-t). ひ es una sonrisa (hi-hi). ふ es una montañita con nubes (fu-ji). へ es una colina (he... sube y baja). ほ es は con una rayita más. ま parece una madeja (ma). み son dos bucles (mi-mi). め es un ojo cerrado (me significa ojo). も es una red de pescar (mo-ri).</p><p class="mt">Última trampa del patrón: no es hu, es <b>fu</b> (suave, soplando).</p><p class="mt">Ya puedes leer: はな (hana, flor), ほし (hoshi, estrella), め (me, ojo), みみ (mimi, oreja), ふね (fune, barco).</p>', '[{"q": "¿Qué sonido es ふ?", "opts": ["fu", "hu", "pu"], "a": 0}, {"q": "¿Qué sonido es め?", "opts": ["me", "mo", "nu"], "a": 0}, {"q": "¿Qué significa ふね (fune)?", "opts": ["barco", "flor", "estrella"], "a": 0}]'::jsonb),
('ja', 5, 'Hiragana 5: Y, R, W y ん (lo último)', '<p class="jp">や ya · ゆ yu · よ yo<br>ら ra · り ri · る ru · れ re · ろ ro<br>わ wa · を wo · ん n</p><p class="mt">Trucos: や parece un yak con cuernos. ゆ es un pez gordo (yu... nada). よ es una llave girada. ら es un pato (ra-pato). る es un lazo con cola (ru tiene rulo). ろ es como る pero sin rulo (ro-jo, sin lazo). わ es una ola (wa-ve). ん es una "n" sola, la única consonante sin vocal.</p><p class="mt">Con esto ya tienes las 46 básicas. を casi no se usa en palabras; se usa como partícula (se pronuncia "o").</p><p class="mt">Ya puedes leer: やま (yama, montaña), ゆき (yuki, nieve), よる (yoru, noche), わたし (watashi, yo), いろ (iro, color).</p>', '[{"q": "¿Qué sonido es ん?", "opts": ["n", "mu", "no"], "a": 0}, {"q": "¿Qué diferencia hay entre る y ろ?", "opts": ["る lleva un rulo abajo y ろ no", "Son el mismo kana", "ろ se lee ru"], "a": 0}, {"q": "¿Qué significa わたし (watashi)?", "opts": ["yo", "noche", "nieve"], "a": 0}]'::jsonb),
('ja', 6, 'Katakana 1: vocales y fila K', '<p class="jp">ア a · イ i · ウ u · エ e · オ o<br>カ ka · キ ki · ク ku · ケ ke · コ ko</p><p class="mt">El katakana se usa para palabras extranjeras (y hay muchas): misma pronunciación que el hiragana, trazos rectos y angulosos.</p><p class="mt">Trucos: ア es un ángulo abierto. イ son dos trazos como una "i". ウ es una casita con tejado. エ es una "I" japonesa. オ es una cruz con palo. カ es como か pero sin el trazo de la derecha. キ parece una llave (ki-y). ケ parece una "K". コ es una caja abierta.</p><p class="mt">Ya puedes leer: ケーキ (kēki, tarta), コーヒー (kōhī, café), カメラ (kamera, cámara), アイス (aisu, helado), エアコン (eakon, aire acondicionado).</p>', '[{"q": "¿Para qué tipo de palabras se usa el katakana?", "opts": ["Para palabras extranjeras", "Para verbos japoneses", "Para nombres de familia"], "a": 0}, {"q": "¿Qué sonido es カ?", "opts": ["ka", "ki", "ko"], "a": 0}, {"q": "¿Qué significa コーヒー (kōhī)?", "opts": ["café", "tarta", "helado"], "a": 0}]'::jsonb)
) as v(lang, day, title, body, quiz)
where not exists (select 1 from lessons l where l.lang = v.lang and l.day = v.day);
